local records={["Core/announcement_data.lua"]={bytes=7929,hash=1709780498,oldBytes=3872,oldHash=1591932332,known={{bytes=2897,hash=2956045427}},changes={{at=1173,current="    return true\nend\nlocal function outputIdentity(value)\n    return type(value)=='string' and value:match('^%x%x%x%x%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%x%x%x%x%x%x%x%x$')~=nil\nend\n-- Output cards are bounded configuration data; imports never execute callbacks.\nfunction addon:IsValidAnnouncementOutput(value,macro)\n    if type(value)~='table' or getmetatable(value)~=nil or not outputIdentity(value.id) then return false end\n    local allowed={id=true,announce=true,value=true,announce_sound=true,emote=true,emote_target=true,conditions=true,disabled=true,channel_name=true}\n    for key in pairs(value) do if not allowed[key] then return false end end\n    if not ({partyraid=true,party=true,raidwarn=true,emote=true,['local']=true,audible=true,gesture=true,say=macro,yell=macro,whisper=macro,channel=macro})[value.announce] then return false end\n    if value.disabled~=nil and type(value.disabled)~='boolean' or value.emote_target~=nil and type(value.emote_target)~='boolean' then return false end\n    if value.value~=nil and (type(value.value)~='string' or #value.value>4096) then return false end\n    if value.announce_sound~=nil and (type(value.announce_sound)~='string' or #value.announce_sound>256) then return false end\n    if value.emote~=nil and (type(value.emote)~='string' or #value.emote>64 or not value.emote:match('^[A-Z][A-Z0-9_]*$')) then return false end\n    if value.announce=='gesture' and value.emote==nil then return false end\n    if value.announce=='audible' and (not value.announce_sound or not value.announce_sound:find('%S')) then return false end\n    if value.channel_name~=nil and (type(value.channel_name)~='string' or #value.channel_name==0 or #value.channel_name>256 or value.channel_name:find('[%z\\1-\\31\\127]')) then return false end\n    if value.announce=='channel' and value.channel_name==nil then return false end\n    if value.conditions~=nil then\n        if type(value.conditions)~='table' or not self.RotationData.CheckPortable(value.conditions) then return false end\n        local result=self.RotationData.ValidateBody({switch=value.conditions,rotation={},cooldowns={}},{conditions=self.conditionDefinitions})\n        if not result.valid or not result.supported then return false end\n    end\n    return true\nend\nlocal function validSeries(owner,value,requireIdentity)\n    if getmetatable(value)~=nil or requireIdentity and not outputIdentity(value.id) then return false end\n    local allowed={id=true,name=true,type=true,spell=true,item=true,ranked=true,event=true,identifier=true,disabled=true,outputs=true}\n    for key in pairs(value) do if not allowed[key] then return false end end\n    for _,key in ipairs({'disabled','ranked'}) do if value[key]~=nil and type(value[key])~='boolean' then return false end end\n    if value.name~=nil and (type(value.name)~='string' or #value.name>256) then return false end\n    local macro=value.type=='macro'\n    if macro then\n        if not owner:IsValidMacroAnnouncementIdentifier(value.identifier) or value.spell~=nil or value.item~=nil or value.ranked~=nil or value.event~=nil then return false end\n    elseif value.type~='spell' and value.type~='pet' and value.type~='item' then return false\n    elseif value.identifier~=nil or type(value.event)~='string' or not (owner.events or {})[value.event] then return false\n    elseif value.type=='item' then if not owner:IsValidAnnouncementItemReference(value.item) then return false end\n    elseif type(value.spell)~='number' or value.spell<=0 or value.spell==math.huge or value.spell%1~=0 then return false end\n    local outputs=value.outputs\n    if type(outputs)~='table' or getmetatable(outputs)~=nil or #outputs>64 then return false end\n    local count,seen=0,{}\n    for index,output in pairs(outputs) do\n        if type(index)~='number' or index<1 or index%1~=0 or index>#outputs or not owner:IsValidAnnouncementOutput(output,macro) or seen[output.id] then return false end\n        count=count+1;seen[output.id]=true\n    end\n    return count==#outputs\nend\nfunction addon:IsValidAnnouncement(value,requireIdentity)\n    if type(value)~='table' then return false end\n    if value.outputs~=nil then return validSeries(self,value,requireIdentity) end\n    if requireIdentity and (type(value.id)~='string' or not value.id:match('^%x%x%x%x%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%x%x%x%x%x%x%x%x$')) then return false end\n    local allowed={name=true,id=true,type=true,spell=true,item=true,ranked=true,disabled=true,event=true,announce=true,value=true,announce_sound=true,emote=true,emote_target=true,conditions=true,identifier=true}\n",previous="    return true\nend\nfunction addon:IsValidAnnouncement(value,requireIdentity)\n    if type(value)~='table' then return false end\n    if requireIdentity and (type(value.id)~='string' or not value.id:match('^%x%x%x%x%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%x%x%x%x%x%x%x%x$')) then return false end\n    local allowed={name=true,id=true,type=true,spell=true,item=true,ranked=true,disabled=true,event=true,announce=true,value=true,announce_sound=true,emote=true,emote_target=true,conditions=true,identifier=true}\n"}}},
["Core/announcements.lua"]={bytes=14827,hash=4225086235,oldBytes=12210,oldHash=2253749734,known={},changes={{at=1562,current="    end\n    return entry,current\nend\n-- One prepared parent lease owns all reached cards. Never prepare a card: that\n-- would replace the parent delivery serial. Public callbacks see a detached view.\nfunction addon:DispatchAnnouncementSeries(parent,recipient,current,targetUnit,format,deliver)\n    local result={chat=false,sound=false,outputs={}}\n    local cards=parent.outputs\n    if type(cards)~='table' or getmetatable(cards)~=nil or #cards>64 or not current() then return result end\n    local count,seen=0,{}\n    for key,card in pairs(cards) do\n        if not current() then return result end\n        if type(key)~='number' or key%1~=0 or key<1 or key>#cards or not self:IsValidAnnouncementOutput(card,parent.type=='macro') or seen[card.id] then return result end\n        if not current() then return result end\n        count=count+1;seen[card.id]=true\n    end\n    if count~=#cards or not current() then return result end\n    for _,card in ipairs(cards) do\n        if not current() then result.retired=true;break end\n        if not card.disabled then\n            local view=self.RotationData.CopyData(card)\n            view.type=parent.type\n            local expected=self.RotationData.CopyData(view)\n            local function live()return current() and same(view,expected) end\n            local matches=self.AnnouncementConditionMatches\n            if not live() then result.retired=true;break end\n            local ok,matched=pcall(matches,self,view,recipient,live,targetUnit)\n            if not live() then result.retired=true;break end\n            if ok and matched and not (view.announce=='gesture' and view.emote_target and not recipient) then\n                local formatted,value=pcall(format,view,live)\n                if not live() then result.retired=true;break end\n                if formatted and value~=nil then\n                    local sent,output\n                    if deliver then sent,output=pcall(deliver,view,value,live)\n                    else\n                        local dispatch=self.DispatchAnnouncement\n                        if not live() then result.retired=true;break end\n                        sent,output=pcall(dispatch,self,view,value,recipient,live)\n                    end\n                    if sent and type(output)=='table' then\n                        result.outputs[#result.outputs+1]=output\n                        result.chat=result.chat or output.chat==true\n                        result.sound=result.sound or output.sound==true\n                    end\n                    if not live() then result.retired=true;break end\n                end\n            end\n        end\n    end\n    return result\nend\n-- Native unit APIs may accept a resolvable name as well as a unit token.\n",previous="    end\n    return entry,current\nend\n-- Native unit APIs may accept a resolvable name as well as a unit token.\n"}}},
["Core/macro_announcements.lua"]={bytes=13389,hash=2302245146,oldBytes=9095,oldHash=3095355608,known={},changes={{at=2517,current="    end\n    return resolved,current\nend\n-- Series may contain independent outputs even when a valid supplied unit is\n-- absent. Preserve that negative observation until the synchronous call ends.\nlocal function seriesTarget(unit)\n    if unit==nil then return nil,function()return true end end\n    if not text(unit,64) or not unit:match('^[a-z][a-z0-9]*$') then return nil,nil,'invalid-unit' end\n    local exists=UnitExists\n    if type(exists)~='function' then return nil,nil,'missing-api' end\n    local ok,present=pcall(exists,unit)\n    if not ok or not platform:CanReadValue(present) or type(present)~='boolean' or exists~=UnitExists then return nil,nil,'target-unavailable' end\n    if present then return target(unit,false) end\n    return nil,function()\n        if exists~=UnitExists then return false end\n        local got,now=pcall(exists,unit)\n        if not got or not platform:CanReadValue(now) then return false end\n        if canaccessvalue and not canaccessvalue(now) then return false end\n        return exists==UnitExists and now==false\n    end\nend\nlocal function seriesSend(view,value,recipient,unit,current,installTargetWitness)\n    local destination=restricted[view.announce]\n    if view.announce=='channel' then destination='CHANNEL' end\n    if not destination then return addon:DispatchAnnouncement(view,value,recipient,current) end\n    if destination=='WHISPER' then\n        local player=UnitIsPlayer\n        if not recipient or not unit or type(player)~='function' or not current() then return failure('target-required') end\n        local ok,isPlayer=pcall(player,unit)\n        if not ok or not platform:CanReadValue(isPlayer) or isPlayer~=true or player~=UnitIsPlayer or not current() then return failure('target-required') end\n    end\n    local fn=type(C_ChatInfo)=='table' and C_ChatInfo.SendChatMessage\n    if type(fn)~='function' then fn=SendChatMessage end\n    if type(fn)~='function' or not current() then return failure('missing-api') end\n    local address=destination=='WHISPER' and recipient or nil\n    local channelCurrent\n    if destination=='CHANNEL' then\n        local resolve=platform.ResolveAnnouncementChannel\n        if type(resolve)~='function' or not current() then return failure('channel-unavailable') end\n        address,channelCurrent=resolve(platform,view.channel_name)\n        if not address or not channelCurrent then return failure('channel-unavailable') end\n        installTargetWitness(channelCurrent)\n    end\n    if not text(value,16384) or not current() then return failure('announcement-retired') end\n    local ok=pcall(fn,value,destination,nil,address)\n    local result={chat=ok,sound=false,chatReason=not ok and 'api-error' or nil}\n    if current() then\n        local audio=addon:DispatchAnnouncement({announce='audible',announce_sound=view.announce_sound},nil,nil,current)\n        result.sound=audio.sound;result.soundReason=audio.soundReason\n    end\n    return result\nend\nlocal function send(textValue,destination,recipient,current)\n",previous="    end\n    return resolved,current\nend\nlocal function send(textValue,destination,recipient,current)\n"},{at=9081,current="    local entry,current=addon:PrepareAnnouncementDelivery(selected,owner)\n    if not entry or not current() then return failure('announcement-retired') end\n    local recipient,unitCurrent,why\n    if entry.outputs~=nil then recipient,unitCurrent,why=seriesTarget(unit)\n    else recipient,unitCurrent,why=target(unit,entry.announce=='whisper') end\n    if not unitCurrent then return failure(why) end\n    targetCurrent=unitCurrent\n",previous="    local entry,current=addon:PrepareAnnouncementDelivery(selected,owner)\n    if not entry or not current() then return failure('announcement-retired') end\n    local recipient,unitCurrent,why=target(unit,entry.announce=='whisper')\n    if not unitCurrent then return failure(why) end\n    targetCurrent=unitCurrent\n"},{at=10124,current="    end\n    if not current() then return failure('announcement-retired') end\n    if entry.outputs~=nil then\n        return addon:DispatchAnnouncementSeries(entry,recipient,current,recipient and unit or nil,function(view)\n            local value=view.value or ''\n            if value:find('{{item}}',1,true) or value:find('{{target}}',1,true) and not recipient or value:find('{{spell}}',1,true) and not link then return nil end\n            return value:gsub('{{target}}',function()return recipient end):gsub('{{spell}}',function()return link end):gsub('{{event}}',function()return L['Via Macro']end)\n        end,function(view,value,live)\n            local previous=targetCurrent\n            if view.announce=='whisper' then\n                local named,whisperCurrent=target(unit,true)\n                if not named or named~=recipient or not whisperCurrent then return failure('target-required') end\n                targetCurrent=function()return previous() and whisperCurrent()end\n            end\n            local function install(witness)\n                local prior=targetCurrent\n                targetCurrent=function()return prior() and witness()end\n            end\n            local ok,result=pcall(seriesSend,view,value,recipient,unit,live,install)\n            targetCurrent=previous\n            return ok and result or failure('api-error')\n        end)\n    end\n    -- Fourth argument is the separately composed event-only context contract.\n    ---@type fun(self: table, config: table, recipient: string|nil, current: function, targetUnit: string|nil): boolean\n",previous="    end\n    if not current() then return failure('announcement-retired') end\n    -- Fourth argument is the separately composed event-only context contract.\n    ---@type fun(self: table, config: table, recipient: string|nil, current: function, targetUnit: string|nil): boolean\n"}}},
["Data/builtin_sources.lua"]={bytes=799968,hash=179410360,oldBytes=799968,oldHash=1697819878,known={{bytes=793994,hash=3465841400},{bytes=793247,hash=18127625}},changes={{at=624072,current="9272ceba597d0202aca8a85e72ca1d1cef3fc4c1129a56f0d8ae9696b8f078e5",previous="ddcafba6e2071bfaaa871272fc1ede1874b7d7a1db4359563f76a4b11b8ecb7d"}}},
["Help/announce.lua"]={bytes=5134,hash=3312792342,oldBytes=4321,oldHash=3362715946,known={{bytes=3573,hash=2751579188}},changes={{at=2306,current="        {id=\"event.FAILED\",title=L[\"Failed\"],text=L[\"Help.Announces.event.FAILED\"]},\n        {id=\"event.DELAYED\",title=L[\"Delayed\"],text=L[\"Help.Announces.event.DELAYED\"]},\n        {id=\"outputs\",title=L[\"Outputs\"],text=L[\"Help.Announces.outputs\"]},\n        {id=\"channel.channel\",title=L[\"Channel\"],text=L[\"Help.Announces.channel.channel\"]},\n        {id=\"announce\",title=L[\"Announce\"],text=L[\"Help.Announces.announce\"]},\n        {id=\"channel.audible\",title=L[\"Audible\"],text=L[\"Help.Announces.channel.audible\"]},\n",previous="        {id=\"event.FAILED\",title=L[\"Failed\"],text=L[\"Help.Announces.event.FAILED\"]},\n        {id=\"event.DELAYED\",title=L[\"Delayed\"],text=L[\"Help.Announces.event.DELAYED\"]},\n        {id=\"announce\",title=L[\"Announce\"],text=L[\"Help.Announces.announce\"]},\n        {id=\"channel.audible\",title=L[\"Audible\"],text=L[\"Help.Announces.channel.audible\"]},\n"},{at=4478,current="    end\nend\n\n-- Card Help uses the same authored document, limited to its output controls.\nfunction addon:GetAnnouncementOutputHelp(kind,mode)\n    local sections={};local included={outputs=true,conditions=true,announce=true,text=true,substitutions=true,state=true,save=true}\n    included['channel.'..tostring(mode)]=true\n    if mode=='gesture' then included.emote=true;included[kind=='macro'and 'macro.emote_target'or 'emote_target']=true end\n    if mode=='audible'then included.sound=true end\n    for _,entry in ipairs(self:GetDocument_layout_announce_options_help())do if included[entry.id]then sections[#sections+1]=entry end end\n    return sections\nend\n",previous="    end\nend\n"}}},
["Locales/enUS.lua"]={bytes=254288,hash=2916484446,oldBytes=251886,oldHash=73360735,known={{bytes=251629,hash=4170098423},{bytes=239063,hash=3242233857},{bytes=240270,hash=1861573959},{bytes=246244,hash=2791749068},{bytes=239398,hash=3083555867},{bytes=239014,hash=4148028330},{bytes=242611,hash=2227579854}},changes={{at=76620,current="L[\"New, Duplicate, Import/Export and Compare\"] = true\nL[\"Help.Announces.editing\"] = \"Announcement details stay always expanded while editing. Press Enter or leave a text field to stage its value; Apply saves the draft. Invalid fields must be corrected before Apply; Discard abandons pending changes. Searchable selectors open on click and filter as you type. The page Help icon explains every option and text substitution.\"\nL[\"Help.Announces.overview\"] = \"Announce selected spell casts or item uses independently of your active rotation, or invoke a configured Via Macro entry directly. Select an entry in the sidebar, or use New to prepare one. The trigger applies to every ordered output card; each card has its own destination and conditions. These settings do not cast spells or use items. Cast-triggered announcements follow RM's combat-data policy and do not run on reference-only clients.\"\nL[\"Help.Announces.name\"] = \"An optional name identifies this announcement in the sidebar. Without one, the action name or Via Macro identifier is used. Changing this display name does not change the watched action or callable identifier.\"\nL[\"Help.Announces.type\"] = \"Choose Spell, Pet Spell, Item or Via Macro. Changing type clears the previous action and exact-rank choice. Via Macro uses an Identifier instead of a cast event or stored action; switching back restores the event selector. Choosing the current type keeps its fields.\"\n",previous="L[\"New, Duplicate, Import/Export and Compare\"] = true\nL[\"Help.Announces.editing\"] = \"Announcement details stay always expanded while editing. Press Enter or leave a text field to stage its value; Apply saves the draft. Invalid fields must be corrected before Apply; Discard abandons pending changes. Searchable selectors open on click and filter as you type. The page Help icon explains every option and text substitution.\"\nL[\"Help.Announces.overview\"] = \"Announce selected spell casts or item uses independently of your active rotation, or invoke a configured Via Macro entry directly. Select an entry in the sidebar, or use New to prepare one. These fields choose the trigger and output; they do not cast spells or use items. Cast-triggered announcements follow RM's combat-data policy and do not run on reference-only clients.\"\nL[\"Help.Announces.name\"] = \"An optional name identifies this announcement in the sidebar. Without one, the action name or Via Macro identifier is used. Changing this display name does not change the watched action or callable identifier.\"\nL[\"Help.Announces.type\"] = \"Choose Spell, Pet Spell, Item or Via Macro. Changing type clears the previous action and exact-rank choice. Via Macro uses an Identifier instead of a cast event or stored action; switching back restores the event selector. Choosing the current type keeps its fields.\"\n"},{at=80186,current="L[\"Help.Announces.event.FAILED\"] = \"The client reported that the cast failed. This is separate from the successful-cast event.\"\nL[\"Help.Announces.event.DELAYED\"] = \"The client reported a delay to the cast. This event is not a completion or success notification.\"\nL[\"Help.Announces.announce\"] = \"Choose a chat destination, local output, a named Emote or Audible. Emote replaces Text with an emote selector and optional recipient. Audible replaces Text with Sound. Text is retained when switching modes. Say, Yell, Whisper and named joined channels are offered only for Via Macro and remain subject to native restrictions.\"\nL[\"Help.Announces.channel.audible\"] = \"Play the selected sound locally on the Master audio channel; no chat message is sent. Choose an available sound before applying the announcement.\"\nL[\"Help.Announces.channel.partyraid\"] = \"Use raid chat while in a raid, party chat while in a party, or your local chat frame while solo.\"\n",previous="L[\"Help.Announces.event.FAILED\"] = \"The client reported that the cast failed. This is separate from the successful-cast event.\"\nL[\"Help.Announces.event.DELAYED\"] = \"The client reported a delay to the cast. This event is not a completion or success notification.\"\nL[\"Help.Announces.announce\"] = \"Choose a chat destination, local output, a named Emote or Audible. Emote replaces Text with an emote selector and optional recipient. Audible replaces Text with Sound. Text is retained when switching modes. Say, Yell and Whisper are offered only for Via Macro and remain subject to native restrictions.\"\nL[\"Help.Announces.channel.audible\"] = \"Play the selected sound locally on the Master audio channel; no chat message is sent. Choose an available sound before applying the announcement.\"\nL[\"Help.Announces.channel.partyraid\"] = \"Use raid chat while in a raid, party chat while in a party, or your local chat frame while solo.\"\n"},{at=84130,current="L[\"Help.Announces.state\"] = \"The pill turns this entry on or off while keeping its fields. Disabled entries do not announce matching casts or macro invocations. Apply saves the changed state.\"\nL[\"Help.Announces.save\"] = \"Edits stay in a draft until Apply. Complete the action or Via Macro identifier and other required fields before saving. Discard abandons changes to saved announcements; Cancel closes a new creation draft. Leaving pending changes offers Apply, Discard or Cancel navigation.\"\nL[\"Help.Announces.collections\"] = \"Use the sidebar buttons to create, duplicate, transfer or compare announcements. Apply saves the imported draft; Compare does not merge entries. Via Macro Duplicate assigns a distinct identifier and every copied output gets a fresh identity. Series exports use version 2; version 1 remains available for legacy single-output entries. Imports and Apply reject ambiguous identifiers. The red trash permanently deletes the selected saved entry after confirmation. Resolve pending edits first; deletion does not carry into the next selected draft.\"\nL[\"Press Enter or leave a text field to stage its value; Apply saves the draft. Invalid text stays red and blocks navigation until corrected. Searchable selectors open on click and filter as you type. Section headings collapse or expand their contents.\"] = true\n\n",previous="L[\"Help.Announces.state\"] = \"The pill turns this entry on or off while keeping its fields. Disabled entries do not announce matching casts or macro invocations. Apply saves the changed state.\"\nL[\"Help.Announces.save\"] = \"Edits stay in a draft until Apply. Complete the action or Via Macro identifier and other required fields before saving. Discard abandons changes to saved announcements; Cancel closes a new creation draft. Leaving pending changes offers Apply, Discard or Cancel navigation.\"\nL[\"Help.Announces.collections\"] = \"Use the sidebar buttons to create, duplicate, transfer or compare announcements. Apply saves the imported draft; Compare does not merge entries. Via Macro Duplicate assigns a distinct identifier. Imports and Apply reject ambiguous identifiers. The red trash permanently deletes the selected saved entry after confirmation. Resolve pending edits first; deletion does not carry into the next selected draft.\"\nL[\"Press Enter or leave a text field to stage its value; Apply saves the draft. Invalid text stays red and blocks navigation until corrected. Searchable selectors open on click and filter as you type. Section headings collapse or expand their contents.\"] = true\n\n"},{at=180091,current="L[\"Edit announcement conditions\"] = \"Edit announcement conditions\"\nL[\"Announcement conditions\"] = \"Announcement conditions\"\nL[\"Help.Announces.conditions\"] = \"Optional conditions use the Announcement condition list and All, Any and Not groups. For spell, pet and item announcements, they run when the configured action and event match. For Via Macro, they run when you invoke the saved identifier. Each output card checks its own conditions. Only a matching result allows that output; unavailable data skips that card while later cards remain independent. In Group can check the Spell recipient recorded for this cast, including click casting, without using your selected target. Choose Announcement target to check the spell recipient for automatic entries, or the supplied unit for Via Macro; Whisper uses that same supplied unit. Automatic entries pass the recorded recipient name to native unit queries. A missing or unresolvable recipient skips its required condition; an unrelated selected target is never substituted. Missing or ambiguous required recipients do not match. Apply in the condition editor updates the announcement draft; Apply on Announces saves it. Cancel or Discard abandons draft changes.\"\n\nL[\"Spell recipient\"] = \"Spell recipient\"\n",previous="L[\"Edit announcement conditions\"] = \"Edit announcement conditions\"\nL[\"Announcement conditions\"] = \"Announcement conditions\"\nL[\"Help.Announces.conditions\"] = \"Optional conditions use the Announcement condition list and All, Any and Not groups. For spell, pet and item announcements, they run when the configured action and event match. For Via Macro, they run when you invoke the saved identifier. Only a matching result allows its message or sound; unavailable data skips the announcement. In Group can check the Spell recipient recorded for this cast, including click casting, without using your selected target. Choose Announcement target to check the spell recipient for automatic entries, or the supplied unit for Via Macro; Whisper uses that same supplied unit. Automatic entries pass the recorded recipient name to native unit queries. A missing or unresolvable recipient skips its required condition; an unrelated selected target is never substituted. Missing or ambiguous required recipients do not match. Apply in the condition editor updates the announcement draft; Apply on Announces saves it. Cancel or Discard abandons draft changes.\"\n\nL[\"Spell recipient\"] = \"Spell recipient\"\n"},{at=192878,current="L['Show this condition in the announcement condition editor.'] = true\nL['Offer this condition type when editing announcement conditions. This flag is independent of Switch Condition and does not remove or invalidate conditions already saved in announcements.'] = true\n-- Ordered announcement outputs (configuration only).\nL['Outputs']='Outputs'\nL['Output %d']='Output %d'\nL['Output state']='Output state'\nL['Add output']='Add output'\nL['Channel']='Channel'\nL['Complete this output or choose a destination available for this action type.']='Complete this output or choose a destination available for this action type.'\nL['Help.Announces.outputs']='One trigger can send an ordered series of outputs. Each expanded card has its own destination, text or sound, conditions and enabled state. Help describes that card. Duplicate makes an independent card; delete removes it. Use the arrows or drag a card to change order. A legacy announcement stays unchanged on display. Adding, duplicating or removing a card, choosing Channel, or changing to an action type that cannot use its saved destination converts only the draft to output cards. Up to 64 outputs are allowed; an empty series sends nothing. Apply saves the draft and Discard restores it.'\nL['Help.Announces.channel.channel']='Via Macro outputs can send to a joined chat channel. Open Channel to refresh the joined names, then select the exact name. A saved name remains visible when unavailable; that output is skipped until the channel is joined under that name. Numeric channel IDs are not saved and channels are never joined automatically. Native delivery permissions still apply.'\n\nL['Choose an announcement trigger, then edit its always expanded output cards. Each card has a destination, conditions, enabled state and Help. Add, duplicate, delete, move or drag outputs within the announcement. Joined channel names are available for Via Macro. New opens a draft; Apply saves it and Discard restores it. Imports are validated and never execute code.']='Choose an announcement trigger, then edit its always expanded output cards. Each card has a destination, conditions, enabled state and Help. Add, duplicate, delete, move or drag outputs within the announcement. Joined channel names are available for Via Macro. New opens a draft; Apply saves it and Discard restores it. Imports are validated and never execute code.'\n\n-- BEGIN GENERATED RM PUBLIC HELPER DOCS\n",previous="L['Show this condition in the announcement condition editor.'] = true\nL['Offer this condition type when editing announcement conditions. This flag is independent of Switch Condition and does not remove or invalidate conditions already saved in announcements.'] = true\n\n-- BEGIN GENERATED RM PUBLIC HELPER DOCS\n"}}},
["Platform/announcement_recipient.lua"]={bytes=8839,hash=3552984198,oldBytes=5366,oldHash=3155682252,known={},changes={{at=4783,current="end\n\n-- Joined names are configuration; local IDs are fresh invocation-only addresses.\nlocal function channelScan(self,current)\n    local query=GetChannelName\n    local readable=self.CanReadValue\n    if type(query)~='function' or type(readable)~='function' then return nil,'missing-api' end\n    local function owned()\n        if current then local ok,live=pcall(current);if not ok or live~=true then return false end end\n        return query==GetChannelName and readable==self.CanReadValue\n    end\n    local function read(value)\n        return readable(self,value) and (not canaccessvalue or canaccessvalue(value))\n    end\n    local rows={}\n    for slot=1,20 do\n        if not owned() then return nil,'announcement-retired' end\n        local ok,id,name=pcall(query,slot)\n        if not ok or not read(id) or not read(name) or not owned() then return nil,'channel-unavailable' end\n        if id~=0 and id~=nil then\n            if type(id)~='number' or id%1~=0 or id<1 or id>20 or type(name)~='string' or name=='' or #name>256 or name:find('[%z\\1-\\31\\127]') then return nil,'channel-unavailable' end\n            rows[#rows+1]={id=id,value=name,text=name}\n        end\n    end\n    if not owned() then return nil,'announcement-retired' end\n    return rows\nend\nfunction platform:GetJoinedAnnouncementChannels(current)\n    local rows,why=channelScan(self,current)\n    if not rows then return nil,why end\n    local result={}\n    for _,row in ipairs(rows) do result[#result+1]={value=row.value,text=row.text} end\n    return result\nend\nfunction platform:ResolveAnnouncementChannel(name,current)\n    if not self:CanReadValue(name) or type(name)~='string' or name=='' or #name>256 or name:find('[%z\\1-\\31\\127]') then return nil,nil,'invalid-channel' end\n    local query,readable=GetChannelName,self.CanReadValue\n    local function resolve()\n        if query~=GetChannelName or readable~=self.CanReadValue then return nil end\n        local rows=channelScan(self,current)\n        if not rows then return nil end\n        local selected\n        for _,row in ipairs(rows) do if row.value==name then if selected then return nil end;selected=row.id end end\n        if not selected or query~=GetChannelName or readable~=self.CanReadValue then return nil end\n        if current then local ok,live=pcall(current);if not ok or live~=true then return nil end end\n        -- A later slot or owner callback can change an earlier address. Finish\n        -- with that selected slot, not the old row from the complete scan.\n        local ok,id,fresh=pcall(query,selected)\n        if not ok or not readable(self,id) or not readable(self,fresh) then return nil end\n        if query~=GetChannelName or readable~=self.CanReadValue then return nil end\n        -- Readability is an extension boundary too. The final native read has\n        -- only native restricted-value guards before its exact comparison.\n        local got,finalID,finalName=pcall(query,selected)\n        if not got then return nil end\n        if canaccessvalue and (not canaccessvalue(finalID) or not canaccessvalue(finalName)) then return nil end\n        if issecretvalue and (issecretvalue(finalID) or issecretvalue(finalName)) then return nil end\n        if query~=GetChannelName or readable~=self.CanReadValue or finalID~=selected or finalName~=name then return nil end\n        return selected\n    end\n    local id=resolve()\n    if not id then return nil,nil,'channel-unavailable' end\n    return id,function()return resolve()==id end\nend\n\n-- BEGIN GENERATED RM SOURCE BINDINGS\ndo\n",previous="end\n\n-- BEGIN GENERATED RM SOURCE BINDINGS\ndo\n"}}},
["UI/collection_compare.lua"]={bytes=13908,hash=1548309674,oldBytes=12669,oldHash=300530493,known={{bytes=12641,hash=238501515}},changes={{at=1244,current="    add(L['Name'],left.name,right.name)\n    if kind=='profile' then\n        local labels={lua_editor=L['Lua editor'],identifier=L['Identifier'],definition=L['Definition'],enable=L['Enable'],poll=L['Polling Interval (seconds)'],ignore_mana=L['Ignore mana'],ignore_range=L['Ignore range'],effect=L['Effect'],color=L['Highlight Color'],magnification=L['Magnification'],setpoint=L['Anchor'],xoffs=L['H'],yoffs=L['V'],loglevel=L['Log Level'],detailed_profiling=L['Detailed Profiling'],disable_autoswitch=L['Disable Auto-Switching'],live_config_update=L['Live Status Update Frequency (seconds)'],spell_history=L['Spell History Memory (seconds)'],combat_history=L['Combat History Memory (seconds)'],damage_history=L['Damage History Memory (seconds)'],disable_buttons=L['Disable Bar Highlighting'],rotation_view=L['Default rotation view'],preview_spells=L['Preview Spells'],preview_window=L['Preview position'],minimap=L['Minimap Icon'],rotations=L['Rotations'],rotationLibrary=L['Rotation library'],itemsets=L['Item Sets'],announces=L['Announces'],outputs=L['Outputs'],channel_name=L['Channel'],condition_groups=L['Categories'],switch_conditions=L['Switch conditions'],other_conditions_order=L['Other'],disabled_conditions=L['Hidden'],name=L['Name'],description=L['Description'],conditions=L['Conditions'],rotation=L['Rotation'],cooldowns=L['Cooldowns'],type=L['Type'],action=L['Action'],unit=L['Unit'],value=L['Value'],spell=L['Spell'],item=L['Item'],items=L['Items'],disabled=L['Disabled'],announce=L['Announce'],event=L['Event'],announce_sound=L['Sound'],emote=L['Emote'],emote_target=L['Use spell recipient ({{target}})'],ranked=L['Use this exact spell rank'],use_name=L['Use step name'],suppress_attack=L['Also suppress implicit Attack'],preview_vertical=L['Vertical'],preview_locked=L['Lock position and size'],preview_opacity=L['Preview windo