back(\\\"OnValueChanged\\\", function(_, _, v)\\010            value.owndebuff = v\\010            top:SetStatusText(funcs:print(root, spec))\\010        end)\\010        parent:AddChild(owndebuff)\\010\\010        local spell_group = addon:Widget_SpellNameWidget(spec, \\\"Spell_EditBox\\\", value,\\010            function() return true end,\\010            function() top:SetStatusText(funcs:print(root, spec)) end,true)\\010        parent:AddChild(spell_group)\\010        parent:AddChild(addon:Widget_AuraRankWidget(value,function() top:SetStatusText(funcs:print(root,spec)) end))\\010\\010        local operator_group = addon:Widget_OperatorWidget(value, L[\\\"Seconds\\\"],\\010            function() top:SetStatusText(funcs:print(root, spec)) end)\\010        parent:AddChild(operator_group)\\010    \",[\"line\"]=101,[\"parameters\"]={\"parent\",\"spec\",\"value\"}}},[\"module\"]=\"Conditions/debuffs.lua\"},[\"DEBUFF_STACKS\"]={[\"callbacks\"]={[\"evaluate\"]={[\"bindings\"]={},[\"code\"]=\"\\010        return addon:EvaluateAuraCondition(value, cache, start, \\\"HARMFUL\\\", \\\"stacks\\\")\\010    \",[\"line\"]=153,[\"parameters\"]={\"value\",\"cache\",\"start\"}},[\"help\"]={[\"bindings\"]={[\"color\"]=\"builtin:Conditions/debuffs.lua:color\",[\"helpers\"]=\"builtin:Conditions/debuffs.lua:helpers\"},[\"code\"]=\"\\010        addon.layout_condition_unitwidget_help(frame)\\010        frame:AddChild(helpers.Gap())\\010        frame:AddChild(helpers.CreateText(color.BLIZ_YELLOW .. L[\\\"Own Debuff\\\"] .. color.RESET .. \\\" - \\\" ..\\010                L[\\\"Only consider auras that you applied yourself.\\\"]))\\010        frame:AddChild(helpers.Gap())\\010        addon.layout_condition_spellnamewidget_help(frame)\\010        addon.layout_condition_aurarank_help(frame)\\010        frame:AddChild(helpers.Gap())\\010        addon.layout_condition_operatorwidget_help(frame, L[\\\"Debuff Stacks\\\"], L[\\\"Stacks\\\"],\\010            L[\\\"Compare the application count of